// Aggregate counts only. No identifiers, form values, query strings or referrers are sent.
export const metricPages=new Set(['index','about','founders','first-edition','gallery','guests','flagship','next-edition','schools','volunteers','contact','school-collaboration','partners','archive','event-flow','event-details','schedule','centsible','faqs','tickets']);
export function metricPage(path){if(!/^\/[^/]*$/.test(path))return null;const name=path==='/'?'index':path.split('/').pop().replace(/\.html$/,'');return metricPages.has(name)?name:null;}
export function metricsAllowed(choice,dnt,gpc){return choice==='yes'&&dnt!=='1'&&!gpc;}
export async function startMetrics(){
 const page=metricPage(location.pathname);if(!page||location.protocol==='file:'||location.hostname==='terminal.local'||window.parent!==window)return;
 let config;try{config=await fetch('/assets/public-config.json').then(r=>r.json());}catch{return;}
 const key='elan-measurement-choice';let choice;try{choice=localStorage.getItem(key);}catch{return;}
 const privacy=()=>navigator.doNotTrack==='1'||navigator.globalPrivacyControl===true;const allowed=()=>metricsAllowed(choice,navigator.doNotTrack,navigator.globalPrivacyControl);
 const sent=new Set();async function record(event){if(!allowed()||sent.has(event))return;sent.add(event);try{const r=await fetch(config.supabaseUrl+'/rest/v1/rpc/elan_record_visit',{method:'POST',keepalive:true,headers:{'Content-Type':'application/json',apikey:config.publishableKey},body:JSON.stringify({p_page:page,p_event:event})});if(!r.ok)sent.delete(event);}catch{sent.delete(event);}}
 const footer=document.querySelector('.footer-legal');if(!footer)return;const button=document.createElement('button');button.type='button';button.className='measurement-choice';button.textContent='Visitor measurement';footer.append(button);
 button.onclick=()=>{const d=document.createElement('dialog');d.className='measurement-dialog';d.innerHTML='<h2>Help us improve Élan</h2><p>Optional measurement counts page views, time spent over 30 seconds, page exits and successful enquiry forms. We send only the page name and event type to our database. We do not record your identity, typed details or browsing history.</p><p>Counts include only visitors who opt in. Your choice is saved in this browser. You can change it here at any time.</p><p class="measurement-state"></p><div class="app-actions"><button data-choice="yes">Allow measurement</button><button data-choice="no" class="secondary">Keep it off</button><button data-close class="secondary">Close</button></div>';d.querySelector('.measurement-state').textContent=privacy()?'Your browser requests privacy, so measurement stays off.':allowed()?'Currently on.':'Currently off.';d.querySelector('[data-choice=yes]').disabled=privacy();for(const b of d.querySelectorAll('[data-choice]'))b.onclick=()=>{choice=b.dataset.choice;try{localStorage.setItem(key,choice);}catch{}d.close();if(allowed()){record('view');arm();}};d.querySelector('[data-close]').onclick=()=>d.close();d.onclose=()=>d.remove();document.body.append(d);d.showModal();};
 let timer;function arm(){clearTimeout(timer);if(allowed()&&!document.hidden)timer=setTimeout(()=>record('engaged'),30000);}document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(timer);else arm();});record('view');arm();window.addEventListener('pagehide',()=>record('exit'));
 document.addEventListener('focusin',e=>{if(e.target.closest('form[data-mode="stored-enquiry"]'))record('form_start');});document.addEventListener('elan:enquiry-saved',()=>record('form_success'));
}
if(typeof document!=='undefined')startMetrics();
